from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class CertificateDetails(SchemaObject):
    authority_key_identifier = SchemaField(name="authorityKeyIdentifier")
    ca_type = SchemaField(name="caType")
    config_dn = SchemaField(name="configDN")
    crl_dp_uri = SchemaField(name="crlDpURI")
    extended_key_usage = SchemaField(name="extendedKeyUsage")
    fingerprint = SchemaField(name="fingerprint")
    issued_by = SchemaField(name="issuedBy")
    issued_to = SchemaField(name="issuedTo")
    key_id_criticality = SchemaField(name="keyIdCriticality")
    key_usage = SchemaField(name="keyUsage")
    serial_number = SchemaField(name="serialNumber")
    signature_algorithm = SchemaField(name="signatureAlgorithm")
    subject_alternate_name = SchemaField(name="subjectAlternateName")
    subject_public_key_algorithm = SchemaField(name="subjectPublicKeyAlgorithm")
    trust_chain = SchemaField(name="trustChain")
    valid_from = SchemaField(name="validFrom")
    valid_to = SchemaField(name="validTo")
    version = SchemaField(name="version")

    def __init__(self, authority_key_identifier, ca_type, config_dn, crl_dp_uri, extended_key_usage, fingerprint,
                 issued_by, issued_to, key_id_criticality, key_usage, serial_number, signature_algorithm,
                 subject_alternate_name, subject_public_key_algorithm, trust_chain, valid_from, valid_to, version):
        self.authority_key_identifier = authority_key_identifier
        self.ca_type = ca_type
        self.config_dn = config_dn
        self.ca_type = ca_type
        self.crl_dp_uri = crl_dp_uri
        self.extended_key_usage = extended_key_usage
        self.fingerprint = fingerprint
        self.issued_by = issued_by
        self.issued_to = issued_to
        self.key_id_criticality = key_id_criticality
        self.key_usage = key_usage
        self.serial_number = serial_number
        self.signature_algorithm = signature_algorithm
        self.subject_alternate_name = subject_alternate_name
        self.subject_public_key_algorithm = subject_public_key_algorithm
        self.trust_chain = trust_chain
        self.valid_from = valid_from
        self.valid_to = valid_to
        self.version = version
        super(CertificateDetails, self).__init__()


class CertificateInfoTRSV1(SchemaObject):
    id = SchemaField(name="id")
    type = SchemaField(name="type")
    details = SchemaField(name="details", klass=CertificateDetails)

    def __init__(self, id, type, details):
        self.id = id
        self.type = type
        self.details = details
        super(CertificateInfoTRSV1, self).__init__()
